#!/usr/bin/env python3
"""Lossless source reconstruction from verified immutable predecessor lines."""
from pathlib import Path,PurePosixPath
import subprocess,hashlib,json
ROOT=Path(__file__).resolve().parents[2]
BASE='808b8f0353051581134d3b8b5a7424422d4e48a8'
DELTAS=json.loads(r'''{"main.tex":{"base":"main.tex","base_sha256":"6a817013b61ebf9bb9123890e2ccf23729c58be01739f993348d273d50edca6b","result_sha256":"56f50d2cfa0d5621762c4f127836266d3b5e9fb38520f93bf8a028fef0f8a9b9","edits":[[41,41,"\\input{revisions/or-r14-20260922/tables/metrics.tex}\n"],[47,48,"Can an externally priced service protocol adapt without reducing customer utility or service? We study persistent tiers, physical stock, costly reconfiguration, and participation at every review. A full-tree balance characterization relates accepted adaptation to continuation prices, boundary scarcity, and switching capacities. Exact payment-transfer coordinates yield sparse critical-friction programs, constructive dual repairs, and profitable accepted deviations. For quadratic resources, verified parameter cells support scalar value experts. An additional price-mediated construction on two-review trees eliminates face enumeration: a specified scalar value derivative generates a feasible policy with a global quadratic regret bound, including binding-capacity transitions. It also gives an explicit critical friction and a sorting-based exact solution. Nonzero-switching experiments connect these results to accepted decisions, independently audited neural proposals, and frozen-policy expected-gain guarantees. Comparisons include structure-aware classical algorithms, offline fitting, exact audits, and actual refinement. Accurate unrefined neural decisions do not imply a complete-pipeline speed advantage, and the paired derivative-training comparison remains statistically unresolved. Earlier information-value results, multistage theory, and unfavorable nonlinear transfer evidence are retained. The resulting framework connects operational acceptance, a learnable decision statistic, and implementable certification without presuming access to the optimal policy.\n"],[51,52,"\\end{minipage}\\vfill{Revision R14, September 22, 2026\\par}\\end{titlepage}\n"],[61,62,"Our third contribution supplies an implementable connection to learning. Arbitrary predicted prices give a loss certificate with explicit switching and commitment penalties. Verified quadratic parameter cells make scalar experts usable without knowing the query-time optimal face. On a two-review tree, a second construction avoids face enumeration entirely: a scalar value derivative identifies a coupling price, and its feasible response has a global quadratic regret bound even across binding-capacity transitions. The same reduction gives an explicit friction threshold and a sorting-based exact solver. Learning now targets a specified operational statistic rather than an unavailable optimal face.\n"],[63,64,"Our fourth contribution executes these connections. Positive-switching multistage experiments trace policy changes through critical friction. A separate scalar-critic study measures eight paired training seeds, unrefined policy quality, and an independent frozen-policy gain guarantee. Matched-accuracy comparisons include structure-aware classical solvers, complete audits, actual refinement, and offline costs. The canonical information hierarchy retains its total accepted improvement of 0.63666527 and inherited-tier contribution of 0.01929038. Severe nonlinear transfer failures remain intact in the companion. The evidence supports accurate accepted neural decisions in specified distributions, not universal speed or a statistically resolved advantage of derivative weighting.\n"],[78,78,"Classical single-resource algorithms already exploit multiplier and breakpoint structure \\citep{PatrikssonStromberg2015}. Our additional contribution identifies the accepted-service reduction and the scalar value derivative that controls its regret, not a new generic multiplier method.\n\n"],[80,83,"\\input{revisions/or-r14-20260922/sections/model.tex}\n\\input{revisions/or-r14-20260922/sections/general_theory.tex}\n\\input{revisions/or-r14-20260922/sections/network_structure.tex}\n"],[87,87,"\\input{revisions/or-r14-20260922/sections/star_bridge.tex}\n"],[88,88,"\\input{revisions/or-r14-20260922/sections/experiment.tex}\n"],[91,94,"Learning enters through a verified value--decision representation rather than an assumed optimal face. On two-review trees, a price-mediated scalar derivative yields a global quadratic regret bound and feasible deployment without storing any face; the absolute friction remains in the decision problem. Arbitrary predicted prices produce a full-horizon certificate with explicit continuation and switching leakage. Quadratic parameter cells make compatible experts usable without solving the query problem first; a learned index is accepted only after its region and policy are checked. Independent validation establishes a positive expected gain over static for a frozen policy in the declared distribution. It does not establish near-optimal raw learning, universal transfer, or superiority over classical cell lookup. The retained nonlinear failures and the new rejection rates identify where refinement remains necessary. Calibrating a service operation, changing tariffs endogenously, and treating private information are distinct extensions, not implicit features of the present model.\n\\paragraph{Preserved scalar precursor.} EC Section~\\ref{sec:r10-tree} reproduces the earlier scalar edge theorem and its complete proof. The more general balance, cut, transfer, and new learning results retain their essential proofs here.\n"],[96,97,"\\clearpage\\input{revisions/or-r14-20260922/sections/references.tex}\n"]]},"electronic_companion.tex":{"base":"electronic_companion.tex","base_sha256":"c2b55112e5e3a6a41f9fae106dc716f42229891b75c16e85f20fb09246a7f9dc","result_sha256":"f6a3ce655eade030686da5e2902b23be0c61c4e7e9b96bc35ba399949296e7b3","edits":[[43,43,"\\input{revisions/or-r14-20260922/tables/metrics.tex}\n"],[46,47,"Revision R14, September 22, 2026\n"],[73,74,"\\input{revisions/or-r10-20260921/sections/tree_structure.tex}\n\\input{revisions/or-r14-20260922/sections/companion.tex}\n\\clearpage\\input{revisions/or-r14-20260922/sections/references.tex}\n"]]},"revisions/or-r14-20260922/sections/model.tex":{"base":"revisions/or-r12-20260922/sections/model.tex","base_sha256":"e1b9e4cb816ea56e20366647714635083fee7d09d7613b1978db2281578d0ec8","result_sha256":"2c93e19bda39fa42a1d42434e30b7a844b39c2aa55138e72aa20f0e80aa0e165","edits":[[28,29,"A fixed retainer $A_0$ can fund provider participation. Total provider profit is $A_0+W^\\pi$ and total customer surplus is $U^\\pi-A_0$; the retainer does not affect policy comparisons. In the canonical inventory study $A_0=6$, $\\nu=2$, and the customer's outside alternative is the best fixed-contract arrangement, including the same retainer. Both that arrangement and the accepted adaptive arrangement satisfy a zero provider outside option. We report incremental $W$ and $U$ so that the historical accounting remains exactly comparable.\n"],[40,41,"The exact expanded-action representation and the provider-relaxation structure are retained in EC Section~\\ref{sec:representation}. The ex ante master agreement above defines the canonical inventory benchmark. The unified formulation below additionally permits an enforceable continuation exit option at every review, implemented by a cap for every nonroot subtree and a root payment equality. The later tree and scalar-critic experiments use that continuation institution; they do not reinterpret an ex ante commitment as a continuation guarantee.\n"]]},"revisions/or-r14-20260922/sections/general_theory.tex":{"base":"revisions/or-r12-20260922/sections/general_theory.tex","base_sha256":"293c3eb66674dc34128ceee81f247de022f9c51cdd510e1f43b03c3991d5abe4","result_sha256":"aacdc1a3804980a11052f980535df8c7c1218ccaa55e4e0fecefbf385936e6bc","edits":[[1,2,"This section supplies a common formulation for the scalar contract model, joint service portfolios, and continuation participation. Critical-fractile analysis and convex first-order optimality are established tools; the supporting-price interpretation identifies their role here. The full-tree cut characterization in Section~\\ref{sec:r12-network} supplies the switching and continuation structure; the earlier scalar edge criterion is retained in EC Section~\\ref{sec:r10-tree}.\n"]]},"revisions/or-r14-20260922/sections/network_structure.tex":{"base":"revisions/or-r12-20260922/sections/network_structure.tex","base_sha256":"d5d4736b6a8c52b8e4c71ce27ff79ff06fd6053f4e886a88e9ffe1a679c5692d","result_sha256":"e45eebdc66aced455e66dd7bf1753afe552d99f23a460aa89b44aea477e31e83","edits":[[1,2,"The scalar edge test in EC Section~\\ref{sec:r10-tree} becomes a capacitated balance condition when changing a tier has an absolute cost. The balance formulation also accommodates nonconstant outside protocols, boundary tiers, several commitments, and vector services. It does not divide by a tariff and therefore remains meaningful for zero or negative net payments. Negative net payments can arise when expected indemnity exceeds the premium; they need not be interpreted as negative gross prices.\n"]]},"revisions/or-r14-20260922/sections/references.tex":{"base":"revisions/or-r13-20260922/sections/references.tex","base_sha256":"8212551bfbe14e16aca7b9f00c34fcbd2a6fdb74303bf5569137cf32e2eb1f17","result_sha256":"ed278ced46809d0dc2c8bca7e5ea00b9ee236b66c9ea87a6ca1422751855933f","edits":[[46,46,"\\bibitem[Patriksson and Str\\\"omberg(2015)]{PatrikssonStromberg2015}\nPatriksson M, Str\\\"omberg C (2015) Algorithms for the continuous nonlinear resource allocation problem---new implementations and numerical studies. arXiv:1501.07035.\n"]]}}''')
for name,record in DELTAS.items():
 p=PurePosixPath(name)
 assert not p.is_absolute() and '..' not in p.parts
 assert name in {'main.tex','electronic_companion.tex'} or name.startswith('revisions/or-r14-20260922/')
 text=subprocess.check_output(['git','show',BASE+':'+record['base']],cwd=ROOT).decode('utf-8')
 assert hashlib.sha256(text.encode()).hexdigest()==record['base_sha256']
 lines=text.splitlines(keepends=True)
 for start,end,replacement in reversed(record['edits']):lines[start:end]=[replacement]
 out=''.join(lines)
 assert hashlib.sha256(out.encode()).hexdigest()==record['result_sha256']
 path=ROOT/name;path.parent.mkdir(parents=True,exist_ok=True);path.write_text(out,encoding='utf-8')
print('Reconstructed',len(DELTAS),'ordinary manuscript source files from exact predecessor objects')
